{"xpath":"","script":"String $temp = xpath(CLTX60);

$tempPostalCode = xpath(/M3OutDocument/DataArea/Document/DocumentHeader/CustomLines/EditedAddress[@Type='1']/ODPONO);
$okecar = xpath(/M3OutDocument/DataArea/Document/DocumentHeader/CustomLines/EditedAddress[@Type='1']/ODECAR);
$okcscd = xpath(/M3OutDocument/DataArea/Document/DocumentHeader/CustomLines/EditedAddress[@Type="1"]/ODCSCD);
$oktown = xpath(/M3OutDocument/DataArea/Document/DocumentHeader/CustomLines/EditedAddress[@Type="1"]/ODCUA4);
$cttx40 = xpath(/M3OutDocument/DataArea/Document/DocumentHeader/CustomLines/EditedAddress[@Type='1']/VFCTR1);
$okecar1 = xpath(/M3OutDocument/DataArea/Document/DocumentHeader/CustomLines/EditedAddress[@Type="1"]/CSTX15);
$iso = xpath(/M3OutDocument/DataArea/Document/DocumentHeader/CustomLines/EditedAddress[@Type="1"]/VFEISO);

if($tempPostalCode == ""){
 $PostalCode = " ";
}else{
 $PostalCode = $tempPostalCode + " ";
}

String $rep1 = replace($temp, '&2', $okecar);
String $rep2 = replace($rep1, '&3', $PostalCode);
String $rep3 = replace($rep2, '&4', $cttx40);
String $rep4 = replace($rep3, '&5', $iso);
String $rep5 = replace($rep4, '&6', $okecar1);
String $rep6 = replace($rep5, '&7', $okcscd);

$AdressLine = replace($rep6, "&1", $oktown);
$AdressLine = replace($AdressLine, '&', "");","isVariable":true,"variableValue":"$AdressLine","hide":{"value":true,"xpath":null,"hideimage":false}}

